const item = $input.first();
// FIX FOR FILESYSTEM BINARY STORE
const buffer = await this.helpers.getBinaryDataBuffer(0, 'file');
const base64Data = buffer.toString('base64');
const mimeType = item.binary.file.mimeType || 'image/png';

const systemPrompt = `Bạn là công cụ trích xuất văn bản (OCR) siêu việt. Hãy trích xuất chính xác 100% các chữ có trong ảnh. Tuyệt đối không tự tóm tắt, không tự sáng tạo nội dung, không giải thích hình ảnh. Giả định bạn đang làm việc với tờ rơi/catalog sản phẩm y khoa, hãy phân tích bố cục và trả về dữ liệu dưới định dạng JSON có cấu trúc chính xác như sau:
{
