const headers = $input.first().json.headers || {};
const body = $input.first().json.body || {};
const adminKey = headers['x-admin-key'] || headers['X-Admin-Key'] || body.adminKey || '';
if (adminKey !== 'Medstand@Admin2026') {
    throw new Error("SECURITY_ALERT: Unauthorized. Only admins can approve catalog.");
}
return [{ json: { 
    itemId: body.itemId,
    action: body.action || 'APPROVE',
    username: body.username || 'admin'
}}];

const item = $input.first().json;
const documentText = `[SẢN PHẨM: ${item.ItemName}]
Mã sản phẩm: ${item.ItemID}
Thành phần: ${item.Ingredients || 'Chưa cập nhật'}
Công dụng chính: ${item.MainUses || 'Chưa cập nhật'}
Đối tượng sử dụng: ${item.TargetPatients || 'Chưa cập nhật'}
Hướng dẫn sử dụng: ${item.UsageInstructions || 'Chưa cập nhật'}
Chống chỉ định: ${item.Contraindications || 'Chưa cập nhật'}
Tác dụng phụ: ${item.SideEffects || 'Chưa cập nhật'}
Từ khóa tìm kiếm: ${item.Keywords || 'Chưa cập nhật'}
Phiên bản: ${item.VersionNo || 1}
Mức tin cậy: ${item.Confidence || 'HIGH'}`;

const textBuffer = Buffer.from(documentText, 'utf8');

return [{
  json: {
    itemId: item.ItemID,
    itemName: item.ItemName,
    status: item.Status,
    version: item.VersionNo,
    confidence: item.Confidence || 'HIGH',
    keywords: item.Keywords || '',
    approvedDate: new Date().toISOString(),
    title: item.ItemName,
    specText: documentText
  },
  binary: {
    file: {
      data: textBuffer.toString('base64'),
      mimeType: 'text/plain',
      fileName: `${item.ItemID}_spec.txt`
    }
  }
}];

